package com.bank.wildcard;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class WildcardCaptureTest {

    // Capture helper: compiler captures ? as T
    static <T> void swapHelper(List<T> list, int i, int j) {
        T temp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, temp);
    }

    static void swap(List<?> list, int i, int j) {
        swapHelper(list, i, j);  // delegate to capture helper!
    }

    @Test
    void wildcardCapture_swapWorks() {
        List<String> accounts = new ArrayList<>(List.of("SAV2001", "CUR3001", "FD4001"));
        swap(accounts, 0, 2);  // works through capture helper!
        assertThat(accounts).containsExactly("FD4001", "CUR3001", "SAV2001");
    }

    @Test
    void wildcardCapture_worksWithAnyType() {
        List<Integer> numbers = new ArrayList<>(List.of(100, 200, 300));
        swap(numbers, 0, 1);
        assertThat(numbers).containsExactly(200, 100, 300);
    }

    // Reading from List<?> is fine
    @Test
    void wildcardRead_asObject() {
        List<?> unknown = List.of("SAV2001", "CUR3001");
        Object first = unknown.get(0);  // reads as Object
        assertThat(first).isEqualTo("SAV2001");
    }
}
